'use client';

/**
 * @file sharedContext.ts
 * @input A registered name and its protocol version
 * @output A React context per key and React, shared by every copy of Core
 *   that runs on that React
 * @position Shared runtime state: a swizzled copy and the package use the same
 *   contexts and stores when their protocol versions match
 */

import {createContext, type Context} from 'react';
import {realmValue, sharedKey} from './sharedRealm';

/**
 * A React context registered under a versioned key, so a provider in one copy
 * of Core reaches consumers in another. Each React gets its own context under
 * the key: a server can load two Reacts, and a streaming render leaves context
 * values that only its own React restores, so requests on two Reacts must not
 * share a context.
 */
export function createSharedContext<T>(
  name: string,
  version: number,
  defaultValue: T,
): Context<T> {
  const byReact = realmValue(
    sharedKey(`context/${name}`, version),
    () => new WeakMap<typeof createContext, Context<unknown>>(),
    value => value instanceof WeakMap,
  );
  const existing = byReact.get(createContext);
  if (existing != null) {
    return existing as Context<T>;
  }
  const SharedContext = createContext(defaultValue);
  SharedContext.displayName = name;
  byReact.set(createContext, SharedContext as Context<unknown>);
  return SharedContext;
}

// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file sharedRealm.ts
 * @input A registered name and its protocol version
 * @output One value per key in the JavaScript realm, shared by every copy of
 *   Core
 * @position Shared runtime state for stores and contexts; no React and no
 *   client directive, so server-safe modules can use it
 */

/**
 * The registered key of a shared value. The version names the value's shape.
 * Change it when a copy built against the old shape cannot read the value.
 * Each copy then keeps its own value.
 */
export function sharedKey(name: string, version: number): symbol {
  return Symbol.for(`@astryxdesign/core/${name}/v${version}`);
}

/**
 * The value under `key` in this JavaScript realm, created on first use. Every
 * copy of Core that asks for the same key gets the same value.
 *
 * The key names the protocol version, so a value found under it has this
 * protocol's shape. `accepts` guards against a key collision: a value it
 * rejects is left in place, and this copy keeps a value of its own.
 */
export function realmValue<T>(
  key: symbol,
  create: () => T,
  accepts: (value: unknown) => boolean = () => true,
): T {
  const realm = globalThis as typeof globalThis & {[key: symbol]: unknown};
  if (Object.hasOwn(realm, key)) {
    const existing = realm[key];
    return accepts(existing) ? (existing as T) : create();
  }
  const value = create();
  realm[key] = value;
  return value;
}
